// Enumeration type
type Months = (January,February,March,April,May,June,July,August,September,October,November,December);

var m: Months;

begin
  m := February;
  writeln(m);
  // Using enumeration type constants after type name is convenient: after dot intellisense shows list of constants
  m := Months.April;
  writeln('Next month: ',m);
  Inc(m);
  writeln('Next month: ',m);
  m := Succ(m);  
  writeln('Next month: ',m);
  m := Pred(m);  
  writeln('Previous month: ',m);
  Dec(m);
  writeln('Previous month: ',m);
  writeln('Its ordinal number (numbering - from zero): ',Ord(m));
  // No error
  writeln('Month before January - out of bounds: ',pred(Months.January));
  // No error
  writeln('Month after December - out of bounds: ',succ(Months.December));
end.

// Enumeration type
uses System;

type Months = (January,February,March,April,May,June,July,August,September,October,November,December);

begin
  var t: &Type := typeof(Months);
  var names: array of string := Enum.GetNames(t);
  writeln('Cycle by enumeration type names');
  foreach name: string in names do
    write(name,' ');
  writeln; writeln;

  var v: &Array := Enum.GetValues(t);
  var mm: array of Months := new Months[v.Length];
  writeln('Cycle by array of all enumeration type values');
  for var i:=0 to v.Length-1 do
    mm[i] := Months(v.GetValue(i));

  for var i:=0 to mm.Length-1 do
    write(mm[i],' ');    
end.

