// "Sieve of Eratosthenes" - computing prime numbers
const n = 100000;

begin
  var primes := HSet(2..n);

  for var i:=2 to Round(Sqrt(n)) do
  begin
    if not (i in primes) then
      continue;
    var x := i*i;
    while x<=n do
    begin
      primes -= x;
      x += i;
    end;
  end;

  Println('Prime numbers <',n,';');
  Println(primes);
  Println;
  Println('Computation time:',Milliseconds/1000);
end.

// E-squares. Recursion demonstration
uses GraphABC;

const mw = 2.9;

procedure ESquares(n,x,y,w: integer);
begin
  var w1 := round(w/mw);
  var h := (w-2*w1) div 3;
  Brush.Color := clRandom;
  Rectangle(x,y,x+w,y+w);
  if n>0 then
  begin
    Sleep(1);
    ESquares(n-1,x+h,y+h,w1);
    ESquares(n-1,x+w-h-w1,y+h,w1);
    ESquares(n-1,x+h,y+w-h-w1,w1);
    ESquares(n-1,x+w-h-w1,y+w-h-w1,w1);
  end;
end;

begin
  Window.Title := 'Recursion: E-squares';
  SetWindowSize(750,530);
  Pen.Color := clWhite;
  ESquares(4,125,18,490);
end.

